final class Custom_Additions {

	/**
	 * Instance unique de cet objet.
	 *
	 * @var object|null
	 */
	protected static $instance = null;

	/**
	 * Renvoyer une instance unique de cet objet.
	 *
	 * @return object
	 */
	public static function get_instance() {
		if ( is_null( self::$instance ) ) {
			self::$instance = new self();
			self::$instance->setup_constants();
			self::$instance->load_textdomain();
			self::$instance->load_dependencies();
			self::$instance->define_admin_hooks();
			self::$instance->define_public_hooks();
			self::$instance->define_shortcodes();
			self::$instance->define_widgets();
			self::$instance->define_post_types();
		}

		return self::$instance;
	}

	/**
	 * Démarrer les constantes du plugin.
	 *
	 * @return void
	 */
	private function setup_constants() {
		// Constants go here.
	}

	/**
	 * Charger les fichiers de base du plugin.
	 *
	 * @return void
	 */
	private function load_dependencies() {
		require_once( plugin_dir_path( __FILE__ ) . 'includes/custom-widgets.php' );
		require_once( plugin_dir_path( __FILE__ ) . 'includes/custom-shortcodes.php' );
		require_once( plugin_dir_path( __FILE__ ) . 'includes/custom-post-types.php' );
	}

	/**
	 * Charger la traduction pour l'interface utilisateur du plugin.
	 *
	 * @return void
	 */
	public function load_textdomain() {
		load_plugin_textdomain(
			'custom_additions',
			false,
			dirname( plugin_basename( __FILE__ ) ) . '/languages/'
		);
	}

