	 * Définir les hooks administrateurs.
	 *
	 * @return void
	 */
	public function define_admin_hooks() {
		// Admin hooks go here.
	}

	/**
	 * Définir les hooks publics.
	 *
	 * @return void
	 */
	public function define_public_hooks() {
		// Public-facing hooks go here.
	}

	/**
	 * Définir les codes courts à l'échelle du site.
	 *
	 * @return void
	 */
	public function define_shortcodes() {
		require_once plugin_dir_path( __FILE__ ) . 'includes/shortcodes/class-shortcodes.php';
		Shortcodes::get_instance();
	}

	/**
	 * Définir les widgets à l'échelle du site.
	 *
	 * @return void
	 */
	public function define_widgets() {
		require_once plugin_dir_path( __FILE__ ) . 'includes/widgets/class-widgets.php';
