import java.util.*;

public class FlowerCategorization {

    private static final Map<String, List<String>> FLORAL_CATEGORIES = new HashMap<>();

    public static void main(String[] args) {
        List<String> flowers = Arrays.asList("Lilac", "Daisy", "Marigold", "Chrysanthemum");

