            addFlowerToList(category, flower);
        }

        System.out.println(FLORAL_CATEGORIES);
    }

    private static String getCategory(String flower, Map<String, Character> categoryMapping) {
        String category = "";
        Character firstChar = Character.toLowerCase(flower.charAt(0));
        if (categoryMapping.containsKey(firstChar + "")) {
            category = categoryMapping.get(firstChar + "");
        }
        return category;
